#!/usr/bin/env python3
"""Genera el visor HTML y las fichas Markdown sin red ni dependencias externas."""
import html
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent
DATA = json.loads((ROOT / 'fuentes.json').read_text())
SOURCES = DATA['sources']
esc = lambda value: html.escape(str(value), quote=True)

notes = ['# Fuentes y fichas de lectura', '', f"Revisadas: {DATA['reviewed_on']}. {DATA['scope']}", '', DATA['confidence_note'], '']
rows = []
for s in SOURCES:
    notes += [f"## {s['id']} · {s['title']}", '', f"{s['authors']} · {s['year'] or 'sin fecha'} · {s['kind']}", '', f"[Fuente original]({s['url']})" + (f" · DOI: {s['doi']}" if s['doi'] else ''), '']
    for label, key in [('Acceso real', 'access'), ('Diseño y muestra', 'design_sample'), ('Hallazgo', 'finding'), ('Límites', 'limitations'), ('Uso práctico', 'application'), ('Confianza aplicada', 'confidence')]:
        notes += [f"**{label}:** {s[key]}", '']
    extra = s.get('supporting_urls', [])
    if extra:
        notes += ['Apoyo documental: ' + ' · '.join(f'[Sitio oficial]({u})' for u in extra), '']
    searchable = ' '.join(str(v) for v in s.values()).casefold()
    fields = ''.join(f'<div><dt>{label}</dt><dd>{esc(s[key])}</dd></div>' for label, key in [('Diseño y muestra','design_sample'),('Qué encontró','finding'),('Qué limita la conclusión','limitations'),('Cómo puede utilizarse','application'),('Acceso consultado','access'),('Confianza para esta aplicación','confidence')])
    support = ''.join(f' <a href="{esc(u)}">Documentación de apoyo</a>' for u in extra)
    rows.append(f'''<details class="paper" id="{s['id']}" data-search="{esc(searchable)}" data-topics="{esc('|'.join(s['topics']))}" data-year="{s['year'] or ''}">
<summary><span class="ref">{s['id']}<small>{s['year'] or 's. f.'}</small></span><span class="paper-heading"><strong>{esc(s['title'])}</strong><span>{esc(s['authors'])} · {esc(s['kind'])}</span></span><span class="expand" aria-hidden="true">+</span></summary>
<div class="paper-body"><p class="topics">{' / '.join(esc(t) for t in s['topics'])}</p><dl>{fields}</dl><p><a href="{esc(s['url'])}">Consultar fuente original</a>{support}</p>{f'<p class="doi">DOI {esc(s["doi"])}</p>' if s['doi'] else ''}</div></details>''')
(ROOT / 'FUENTES.md').write_text('\n'.join(notes))
topics = sorted({t for s in SOURCES for t in s['topics']}, key=str.casefold)
options = ''.join(f'<option value="{esc(t)}">{esc(t)}</option>' for t in topics)
template = '''<!doctype html>
<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><title>Biblioteca del entrenador · Escalada</title>
<style>
:root{--ink:#163149;--blue:#205d83;--paper:#fff;--ground:#edf3f7;--line:#cbd9e2;--soft:#52687a;--accent:#ad4d1b;--focus:#005fcc}*{box-sizing:border-box}body{margin:0;background:var(--ground);color:var(--ink);font:17px/1.6 'Avenir Next',Avenir,'Segoe UI',sans-serif}a{color:var(--blue);text-underline-offset:3px}a:hover{text-decoration-thickness:2px}:focus-visible{outline:3px solid var(--focus);outline-offset:4px}.skip{position:absolute;top:-80px;background:white;padding:12px;z-index:5}.skip:focus{top:0}.shell{max-width:1460px;margin:auto;display:grid;grid-template-columns:250px minmax(0,1fr);min-height:100vh}aside{background:var(--ink);color:#fff;padding:40px 28px;position:sticky;top:0;height:100vh;overflow:auto}aside a{color:#f0f7fc;display:block;padding:9px 0;font-size:15px}.brand{font-weight:750;font-size:23px;line-height:1.2;margin:0 0 12px}.side-note{color:#d3e1ec;font-size:14px;margin:0 0 32px}.side-title{border-top:1px solid #4b6477;padding-top:25px;margin-top:30px;font-weight:650}.side-footer{font-size:13px;color:#d3e1ec;margin-top:40px}main{min-width:0;padding:48px 5vw 70px}.heading-line{display:flex;justify-content:space-between;gap:20px;align-items:baseline;font-size:14px;color:var(--soft);padding-bottom:18px;border-bottom:1px solid var(--line)}h1{font-size:clamp(36px,4.5vw,65px);font-weight:700;letter-spacing:-2px;line-height:1.08;max-width:820px;margin:34px 0 24px}h2{font-size:27px;letter-spacing:-.5px;line-height:1.25;margin:0 0 15px}p{max-width:76ch}.intro{font-size:20px;max-width:67ch;color:#3a5367}.scope{border-left:4px solid var(--accent);padding:4px 0 4px 20px;margin:28px 0 38px}.scope p{margin:0;font-size:15px}.principles{display:grid;grid-template-columns:1fr 1fr;gap:20px 35px;border-block:1px solid var(--line);padding:25px 0;margin-bottom:40px}.principles h3{font-size:17px;margin:0 0 5px}.principles p{font-size:15px;color:var(--soft);margin:0}.filters{background:var(--paper);padding:22px;border:1px solid var(--line);display:grid;grid-template-columns:2fr 1fr 1fr;gap:14px;margin-top:24px}.filters label{font-size:14px;font-weight:600}.filters input,.filters select{width:100%;font:inherit;font-size:16px;color:var(--ink);background:#fff;border:1px solid #9bb1c1;border-radius:4px;padding:11px 9px;margin-top:6px;min-height:46px}.toolbar{display:flex;justify-content:space-between;align-items:center;gap:15px;margin:16px 0;font-size:14px}.toolbar button{background:transparent;border:0;color:var(--blue);font:inherit;text-decoration:underline;cursor:pointer;min-height:40px}.papers{background:white;border:1px solid var(--line)}.paper{border-bottom:1px solid var(--line);scroll-margin-top:20px}.paper:last-child{border-bottom:0}.paper[hidden]{display:none}.paper summary{display:flex;gap:20px;align-items:flex-start;list-style:none;padding:24px;cursor:pointer}.paper summary::-webkit-details-marker{display:none}.paper summary:hover{background:#f5f9fb}.ref{font-size:14px;font-weight:700;min-width:44px;color:var(--blue);padding-top:3px}.ref small{display:block;font-size:12px;font-weight:400;color:var(--soft);margin-top:3px}.paper-heading{flex:1;min-width:0}.paper-heading strong{display:block;font-size:18px;font-weight:650;line-height:1.45}.paper-heading>span{display:block;font-size:13px;color:var(--soft);margin-top:8px}.expand{font-size:27px;line-height:1.2;color:var(--blue)}.paper[open] .expand{transform:rotate(45deg)}.paper-body{padding:0 28px 26px 88px;font-size:15px}.topics{color:var(--accent);font-size:13px;font-weight:600}dl{margin:18px 0}dl>div{margin-bottom:15px}dt{font-weight:700}dd{margin:3px 0 0;color:#3a5367;max-width:72ch}.doi{font-size:12px;overflow-wrap:anywhere;color:var(--soft)}.guide{margin-top:48px}.guide-links{display:grid;grid-template-columns:1fr 1fr;gap:12px 28px}.guide-links a{display:block;border-bottom:1px solid var(--line);padding:15px 0}.guide-links small{display:block;color:var(--soft);font-size:14px}.empty{padding:30px;margin:0}footer{border-top:1px solid var(--line);font-size:13px;color:var(--soft);margin-top:45px;padding-top:20px}.nojs{font-size:14px;color:var(--soft)}@media(max-width:900px){.shell{grid-template-columns:200px minmax(0,1fr)}aside{padding:30px 18px}main{padding:35px 25px}.filters{grid-template-columns:1fr 1fr}.filters label:first-child{grid-column:1/-1}}@media(max-width:650px){.shell{display:block}aside{position:static;height:auto;padding:22px}.brand{font-size:21px;margin-bottom:8px}.side-note{margin-bottom:12px}.primary-nav{display:flex;flex-wrap:wrap;gap:5px 22px}.side-title,.reference-nav,.side-footer{display:none}main{padding:26px 19px 45px}h1{letter-spacing:-1px}.heading-line{font-size:12px}.intro{font-size:18px}.principles,.guide-links{grid-template-columns:1fr}.filters{padding:16px;gap:12px}.paper summary{padding:19px 14px;gap:12px}.paper-heading strong{font-size:16px}.paper-body{padding:0 18px 22px 18px}.ref{min-width:38px}.toolbar{align-items:flex-start}}@media print{aside,.filters,.toolbar{display:none}.shell{display:block}main{padding:0}.paper-body{display:block!important}details{break-inside:avoid}.papers{border:0}body{background:white;font-size:11pt}h1{font-size:30pt}}
</style></head><body><a class="skip" href="#contenido">Saltar al contenido</a><div class="shell"><aside><p class="brand">Cuaderno del entrenador</p><p class="side-note">Escalada y acondicionamiento físico</p><nav class="primary-nav" aria-label="Contenido"><a href="#biblioteca">Consultar evidencia</a><a href="#herramientas">Guías y plantillas</a><a href="../AGENTS.md">Instrucciones del agente</a></nav><p class="side-title">Lectura de partida</p><nav class="reference-nav" aria-label="Fuentes iniciales"><a href="#S05">Fiabilidad de los tests</a><a href="#S13">Medir con Tindeq</a><a href="#S12">Entrenar en tabla</a><a href="#S23">Acondicionamiento · 2026</a><a href="#S38">Nutrición · 2026</a></nav><p class="side-footer">Notas originales y fuentes enlazadas.<br>Revisión: 16 octubre 2026.</p></aside>
<main id="contenido"><header><div class="heading-line"><span>Biblioteca de investigación</span><span>Edición inicial · 16/10/2026</span></div><h1>Entrenar con criterio.<br>Revisar con datos.</h1><p class="intro">Una base de consulta para elegir qué entrenar, medir la respuesta y ajustar el plan. Cada fuente conserva su resultado, sus límites y su aplicación posible.</p><div class="scope"><p><strong>__COUNT__ fuentes, con trabajos de 2026.</strong> Revisión rápida aplicada; cobertura no exhaustiva. La fecha reciente no sustituye a un buen diseño. Las fichas indican si se consultó texto completo, resumen o documentación.</p></div></header>
<section class="principles" aria-label="Principios de lectura"><div><h3>Una tabla no equivale a otra</h3><p>Conservar ángulo, configuración y presas. Separar repeticiones conocidas de problemas nuevos.</p></div><div><h3>Un test no es un encadene</h3><p>Fuerza, técnica, continuidad y recuperación aportan información distinta.</p></div><div><h3>La dosis tiene un coste</h3><p>MoonBoard, cuerda, suspensiones y campus pueden acumular carga sobre los mismos tejidos.</p></div><div><h3>El plan sigue abierto</h3><p>Esta investigación no cambia fases o fechas. La progresión se revisa con resultados comparables.</p></div></section>
<section id="biblioteca"><h2>Fuentes y fichas de lectura</h2><p>Busca un método, autor o tema. Abre una ficha para leer qué permite concluir y qué deja pendiente.</p><div class="filters"><label>Buscar<input id="buscar" type="search" placeholder="MoonBoard, sensor, fuerza, recuperación…" autocomplete="off"></label><label>Tema<select id="tema"><option value="">Todos los temas</option>__OPTIONS__</select></label><label>Publicación<select id="periodo"><option value="">Todos los años</option><option value="2026">2026</option><option value="reciente">2024–2026</option></select></label></div><noscript><p class="nojs">Las fichas se pueden abrir sin JavaScript. Los filtros requieren JavaScript.</p></noscript><div class="toolbar"><span id="cuenta" role="status" aria-live="polite">__COUNT__ fuentes disponibles</span><button id="limpiar" type="button">Restablecer filtros</button></div><div class="papers">__ROWS__<p id="vacio" class="empty" hidden>No hay fuentes para esos filtros. Prueba con otro término o restablécelos.</p></div></section>
<section class="guide" id="herramientas"><h2>Del estudio a la decisión</h2><p>Las guías enlazadas están en Markdown para que el agente pueda consultarlas y mantenerlas. Las plantillas son registros vacíos, no datos realizados.</p><div class="guide-links"><a href="EVIDENCIA.md">Mapa de evidencia<small>Qué respalda cada método y qué sigue incierto.</small></a><a href="MANUAL_ENTRENADOR.md">Manual del entrenador<small>Objetivos, sesiones, carga y acondicionamiento.</small></a><a href="FUERZA_Y_METRICAS.md">Fuerza máxima, RFD y CF<small>Qué mide cada variable y qué no permite concluir.</small></a><a href="PROTOCOLOS.md">Evaluación y sensor<small>Fuerza, repetibilidad, unidades y errores.</small></a><a href="CONTEXTO_DEPORTISTA.md">Contexto fechado<small>Material, resultados y decisiones pendientes.</small></a><a href="METODOLOGIA.md">Método de investigación<small>Búsquedas, selección y actualización.</small></a><a href="plantillas/revision_bloque.md">Revisión de bloque<small>Documentar logros, ajustes y próxima evaluación.</small></a><a href="plantillas/sesion.json">Plantilla de sesión<small>Trabajo realizado, descansos y calidad.</small></a><a href="plantillas/test_sensor.json">Plantilla del sensor<small>Montaje y resultados sin mediciones inventadas.</small></a></div></section><footer>Catálogo estructurado: <a href="fuentes.json">JSON</a> · <a href="FUENTES.md">Markdown</a>. Los niveles de confianza son valoraciones locales, no GRADE formal. HTML facilita consultar; las instrucciones del agente viven en AGENTS.md.</footer></main></div>
<script>
const buscar=document.getElementById('buscar'),tema=document.getElementById('tema'),periodo=document.getElementById('periodo'),papers=[...document.querySelectorAll('.paper')];
const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('es');
function filtrar(){const q=normalize(buscar.value.trim());let n=0;for(const paper of papers){const year=Number(paper.dataset.year);const match=normalize(paper.dataset.search).includes(q)&&(!tema.value||paper.dataset.topics.split('|').includes(tema.value))&&(!periodo.value||(periodo.value==='reciente'?year>=2024&&year<=2026:year===2026));paper.hidden=!match;if(match)n++;}document.getElementById('cuenta').textContent=n+' de '+papers.length+' fuentes';document.getElementById('vacio').hidden=n!==0;}
for(const control of [buscar,tema,periodo])control.addEventListener('input',filtrar);
document.getElementById('limpiar').addEventListener('click',()=>{buscar.value='';tema.value='';periodo.value='';filtrar();buscar.focus();});
function abrirAncla(){const target=document.getElementById(location.hash.slice(1));if(target&&target.classList.contains('paper')){if(target.hidden){buscar.value='';tema.value='';periodo.value='';filtrar();}target.open=true;target.scrollIntoView({block:'start'});}}
window.addEventListener('hashchange',abrirAncla);abrirAncla();
</script></body></html>
'''
(ROOT / 'index.html').write_text(template.replace('__OPTIONS__', options).replace('__ROWS__', '\n'.join(rows)).replace('__COUNT__', str(len(SOURCES))))
print(f'Generadas {len(SOURCES)} fichas y visor HTML.')
